"""Sample product URLs from retailers' own sitemaps, under ECDEV's robots evaluator.
python -I discover.py <helper> <out seeds.json>
Per host: robots.txt -> ECDEV evaluator + AI-agent policy -> Sitemap lines -> sitemap (gz ok) ->
first child whose URL looks like a product sitemap -> 2 URLs evenly spaced. 2 s per host minimum."""
import gzip, json, re, subprocess, sys, time, urllib.parse, requests
helper, out = sys.argv[1], sys.argv[2]
UA = "ECDEV/0.1 (+read-only research)"
S = requests.Session(); S.headers["User-Agent"] = UA
HOSTS = """www.allbirds.com www.gymshark.com kith.com www.fashionnova.com colourpop.com bombas.com www.brooklinen.com casper.com www.warbyparker.com www.glossier.com rothys.com ruggable.com www.mejuri.com www.hm.com www.asos.com www.nike.com www.adidas.com www.newbalance.com us.puma.com www.patagonia.com www.rei.com www.backcountry.com www.bhphotovideo.com www.newegg.com www.bestbuy.com www.walmart.com www.target.com www.costco.com www.homedepot.com www.lowes.com www.wayfair.com www.etsy.com www.macys.com www.nordstrom.com www.kohls.com www.gap.com www.lululemon.com www.sephora.com www.ulta.com www.dyson.com www.sonos.com www.lego.com www.chewy.com www.petco.com www.ikea.com www.uniqlo.com www.zappos.com www.decathlon.com www.muji.com www.nitori-net.jp www.biccamera.com www.yodobashi.com www.askul.co.jp www.loft.co.jp www.amazon.com www.ebay.com www.aliexpress.com www.otto.de www.zalando.de www.argos.co.uk www.johnlewis.com www.currys.co.uk www.mediamarkt.de www.cdiscount.com www.bol.com www.allegro.pl www.mercadolibre.com.mx www.flipkart.com www.coupang.com www.shopee.sg www.rakuten.co.jp www.zozo.jp store.steampowered.com www.thomann.de www.rs-online.com www.digikey.com www.mouser.com www.grainger.com www.staples.com www.officedepot.com www.sweetwater.com www.crutchfield.com www.adorama.com www.ssense.com www.farfetch.com www.revolve.com www.anthropologie.com www.urbanoutfitters.com www.madewell.com www.jcrew.com www.eddiebauer.com www.llbean.com www.columbia.com www.thenorthface.com www.hoka.com www.on.com www.brooksrunning.com""".split()
def j(*a): return json.loads(subprocess.check_output([helper, *a]))
last = {}
def get(url, host):
    w = 2 - (time.time() - last.get(host, 0))
    if w > 0: time.sleep(w)
    try: r = S.get(url, timeout=25)
    except Exception as e: return None
    last[host] = time.time(); return r
seeds, log = [], []
for host in HOSTS:
    rec = {"host": host}
    r = get(f"https://{host}/robots.txt", host)
    if r is None or r.status_code != 200:
        rec["result"] = "ROBOTS_UNAVAILABLE_%s" % (r.status_code if r is not None else "ERR"); log.append(rec); continue
    pth = f"/tmp/claude-0/robots-{host}.txt"; open(pth, "w").write(r.text)
    ai = j("aipolicy", pth, "https://%s/" % host)
    if ai.get("refusal"):
        rec["result"] = "AI_AGENT_REFUSED"; rec["ai_policy"] = ai; log.append(rec); continue
    maps = re.findall(r"(?im)^\s*sitemap:\s*(\S+)", r.text)
    rec["sitemaps"] = len(maps)
    def fetch_map(u):
        rr = get(u, host)
        if rr is None or rr.status_code != 200: return None
        b = rr.content
        if b[:2] == b"\x1f\x8b":
            try: b = gzip.decompress(b)
            except Exception: return None
        return b.decode("utf-8", "replace")
    urls = []
    cand = maps[:6]
    prod = [m for m in maps if re.search(r"product|item|/p[-_]|catalog", m, re.I)]
    for m in (prod or cand)[:2]:
        t = fetch_map(m)
        if not t: continue
        locs = re.findall(r"<loc>\s*([^<\s]+)\s*</loc>", t)
        if "<sitemapindex" in t:
            kids = [k for k in locs if re.search(r"product|item|catalog", k, re.I)] or locs
            for k in kids[:1]:
                t2 = fetch_map(k)
                if t2: urls += re.findall(r"<loc>\s*([^<\s]+)\s*</loc>", t2)
        else: urls += locs
        if urls: break
    urls = [u for u in urls if urllib.parse.urlsplit(u).netloc == host and not u.endswith((".jpg", ".png", ".xml", ".gz"))]
    rec["urls_seen"] = len(urls)
    if len(urls) < 2: rec["result"] = "NO_PRODUCT_URLS"; log.append(rec); continue
    pick = [urls[len(urls)//5], urls[len(urls)*3//5]]
    for u in pick: seeds.append({"site": host, "kind": "product", "url": u})
    rec["result"] = "OK"; log.append(rec)
    print(host, rec["result"], flush=True)
json.dump(seeds, open(out, "w"), indent=1); json.dump(log, open(out + ".log.json", "w"), indent=1)
print(len(seeds), "seeds")
